 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld || R.AssetPath.IsEmpty() || R.AssetPath.Len()>2048 || R.BlockIndex<0 || R.Count<1 || R.Count>128) throw std::runtime_error("Stopped editor/bounded loaded sequence/pages1..128 required"); auto* Sequence=LoadObject<ULevelSequence>(nullptr,*R.AssetPath); auto* Scene=IsValid(Sequence)?Sequence->GetMovieScene():nullptr; if(!IsValid(Sequence) || !Sequence->IsAsset() || Sequence->IsTemplate() || Sequence->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || Sequence->GetPathName()!=R.AssetPath || !IsValid(Scene)) throw std::runtime_error("Exact loaded persistent sequence required"); const FString Before=State(Scene,Scene->AllTaggedBindings()); const bool Inspect=R.FieldName==TEXT("Inspect"),Create=R.FieldName==TEXT("Create"),Tag=R.FieldName==TEXT("TagRootBinding"),Untag=R.FieldName==TEXT("UntagRootBinding"),Remove=R.FieldName==TEXT("RemoveTag"),Rename=R.FieldName==TEXT("RenameTag"); bool Changed=false;
 if(!Inspect) { if(!GEditor->Trans || !R.bConfirm || Scene->IsReadOnly() || Sequence->GetClass()->GetPathName()!=R.ExpectedClassPath || R.ExpectedAssetSnapshot.IsEmpty() || R.ExpectedAssetSnapshot.Len()>262144 || R.ExpectedAssetSnapshot!=Before || R.Name.IsEmpty() || R.Name.Len()>128 || R.Name.TrimStartAndEnd()!=R.Name || (!Create && !Tag && !Untag && !Remove && !Rename)) throw std::runtime_error("Confirmed writable sequence/class/full tag snapshot/bounded trimmed tag/supported operation required"); for(TCHAR C:R.Name) if(C<32) throw std::runtime_error("Tag cannot contain controls"); const FName Name(*R.Name); if(Name.IsNone()) throw std::runtime_error("Non-None native tag name required"); auto Expected=Scene->AllTaggedBindings(); const auto* Existing=Expected.Find(Name); if((Existing!=nullptr)!=R.bExpectedEnabled) throw std::runtime_error("Exact prior tag group existence required"); FGuid Guid; UE::MovieScene::FFixedObjectBindingID Fixed; FName NewName; FMovieSceneObjectBindingIDs PreservedGroup; FMapProperty* GroupsProperty=nullptr;
 if(Tag || Untag) { if(!FGuid::Parse(R.ActorGuid,Guid) || !Guid.IsValid() || !Scene->FindBinding(Guid)) throw std::runtime_error("Current selected-sequence root binding GUID required"); Fixed=UE::MovieScene::FFixedObjectBindingID(Guid,MovieSceneSequenceID::Root); const FMovieSceneObjectBindingID Serialized=Fixed; if(Tag) { auto& Group=Expected.FindOrAdd(Name); if(!Group.IDs.Contains(Serialized) && Group.IDs.Num()>=256) throw std::runtime_error("Tag member insertion budget256 exceeded"); Group.IDs.AddUnique(Serialized); } else { auto* Group=Expected.Find(Name); if(!Group || !Group->IDs.Contains(Serialized)) throw std::runtime_error("Exact fixed-root binding membership required for untag"); Group->IDs.Remove(Serialized); if(Group->IDs.IsEmpty()) Expected.Remove(Name); } }
 else if(Rename) { if(!Existing || R.OutputName.IsEmpty() || R.OutputName.Len()>128 || R.OutputName.TrimStartAndEnd()!=R.OutputName) throw std::runtime_error("Existing tag and bounded trimmed destination name required"); for(TCHAR C:R.OutputName) if(C<32) throw std::runtime_error("Destination tag cannot contain controls"); NewName=FName(*R.OutputName); if(NewName.IsNone()) throw std::runtime_error("Non-None destination tag required"); if(NewName!=Name) { if(Expected.Contains(NewName) || !R.bEnabled) throw std::runtime_error("Absent destination tag and explicit name-consumer breakage opt-in required"); GroupsProperty=FindFProperty<FMapProperty>(Scene->GetClass(),TEXT("BindingGroups")); const auto* Value=GroupsProperty?CastField<FStructProperty>(GroupsProperty->ValueProp):nullptr; if(!GroupsProperty || !CastField<FNameProperty>(GroupsProperty->KeyProp) || !Value || Value->Struct!=FMovieSceneObjectBindingIDs::StaticStruct()) throw std::runtime_error("Native binding-group map reflection unavailable"); PreservedGroup=*Existing; Expected.Remove(Name); Expected.Add(NewName,PreservedGroup); } }
 else if(Create) { if(Existing || Expected.Num()>=256) throw std::runtime_error("New absent tag/budget256 required; native AddNewBindingTag would overwrite an existing group"); Expected.Add(Name,FMovieSceneObjectBindingIDs()); } else { if(!Existing || (Existing->IDs.Num()>0 && !R.bEnabled)) throw std::runtime_error("Existing tag required; deleting populated tag requires explicit breakage opt-in"); Expected.Remove(Name); }
 const FString ExpectedState=State(Scene,Expected); Changed=Before!=ExpectedState; if(Changed && !R.bDryRun) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Edit Sequencer Binding Tags"))); Sequence->Modify(); Scene->Modify(); if(State(Scene,Scene->AllTaggedBindings())!=Before || ((Tag || Untag) && !Scene->FindBinding(Guid))) throw std::runtime_error("Binding tag context changed before edit"); if(Create) Scene->AddNewBindingTag(Name); else if(Tag) Scene->TagBinding(Name,Fixed); else if(Untag) Scene->UntagBinding(Name,Fixed); else if(Rename) { Scene->RemoveTag(Name); Scene->AddNewBindingTag(NewName); auto* Groups=GroupsProperty->ContainerPtrToValuePtr<TMap<FName,FMovieSceneObjectBindingIDs>>(Scene); Groups->FindChecked(NewName)=PreservedGroup; } else Scene->RemoveTag(Name); Scene->MarkAsChanged(); if(State(Scene,Scene->AllTaggedBindings())!=ExpectedState) throw std::runtime_error("Native binding tag/full groups readback failed"); Sequence->MarkPackageDirty(); } }
 const auto& Groups=Scene->AllTaggedBindings(); TArray<FName> Names; Groups.GetKeys(Names); Names.Sort([](FName A,FName B){ return A.ToString()<B.ToString(); }); const int32 Start=FMath::Min(R.BlockIndex,Names.Num()),End=Start+FMath::Min(R.Count,Names.Num()-Start); const FString Current=State(Scene,Groups); FString Json; auto J=TJsonWriterFactory<>::Create(&Json); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("sequence_class_path"),Sequence->GetClass()->GetPathName()); J->WriteValue(TEXT("total_groups"),Names.Num()); J->WriteValue(TEXT("next_start"),End); J->WriteValue(TEXT("has_more"),End<Names.Num()); J->WriteValue(TEXT("snapshot_character_count"),Current.Len()); J->WriteValue(TEXT("snapshot_within_edit_budget"),Current.Len()<=262144); if(Current.Len()<=262144) J->WriteValue(TEXT("binding_tags_snapshot"),Current); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("written"),Changed && !R.bDryRun); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteArrayStart(TEXT("groups")); for(int32 K=Start;K<End;++K) { const auto& Group=Groups.FindChecked(Names[K]); J->WriteObjectStart(); J->WriteValue(TEXT("name"),Names[K].ToString()); J->WriteValue(TEXT("member_count"),Group.IDs.Num()); J->WriteValue(TEXT("native_group_snapshot"),GroupText(Group)); J->WriteArrayStart(TEXT("bindings")); for(const auto& Id:Group.IDs) { const bool Root=Id.IsFixedBinding() && Id.GetRelativeSequenceID()==MovieSceneSequenceID::Root; J->WriteObjectStart(); J->WriteValue(TEXT("guid"),Id.GetGuid().ToString()); J->WriteValue(TEXT("fixed_binding"),Id.IsFixedBinding()); J->WriteValue(TEXT("fixed_root_binding"),Root); J->WriteValue(TEXT("selected_scene_binding_exists"),Root && Scene->FindBinding(Id.GetGuid())!=nullptr); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("scope"),TEXT("Native binding tag groups Inspect/Create/TagRootBinding/UntagRootBinding/RemoveTag/RenameTag, full sorted group-name/native serialized IDs snapshot/class/prior existence/confirmation/writable guards, max256 groups/members/pages128/input256KiB; export unbounded before cap. Root operations treat selected sequence as root and require existing local binding, no hierarchy remap/nested binding ID authoring. Native untag deletes empty group; Create rejects existing group to avoid native overwrite; populated RemoveTag requires breakage opt-in, no complete name-based/unloaded consumer audit. RenameTag requires absent destination/name-consumer breakage opt-in and copies exact native serialized group through checked reflected map after native remove-create, preserving nested/relative IDs without reinterpretation; case-equivalent native name is no-op. External consumers not migrated. Transaction/native helpers/MarkAsChanged/full groups readback/dirty/no-op/dry-run. No binding body edits/player resolution/evaluation/playhead/events/render/compile/load/save; UI/cache/undo/persistence unverified.")); J->WriteObjectEnd(); J->Close(); return Json;
